"""
title: Crypto Price Tool
author: greg
description: Real-time cryptocurrency prices, 24h change, market cap, and volume via CoinGecko (free, no API key required)
version: 1.0
"""

from datetime import datetime, timezone

import requests
from pydantic import BaseModel, Field


class Tools:
    class Valves(BaseModel):
        vs_currency: str = Field(
            default="usd",
            description="Default currency to price against when the user doesn't specify one (e.g. usd, eur, btc)",
        )
        timeout_seconds: int = Field(
            default=10,
            description="HTTP request timeout in seconds",
        )

    def __init__(self):
        self.valves = self.Valves()
        self.citation = True

    def _resolve_coin(self, query: str):
        """Resolve a free-text coin name or ticker symbol to a CoinGecko coin id via the search endpoint."""
        try:
            resp = requests.get(
                "https://api.coingecko.com/api/v3/search",
                params={"query": query},
                timeout=self.valves.timeout_seconds,
            )
            resp.raise_for_status()
            coins = resp.json().get("coins", [])
        except requests.RequestException:
            return None

        if not coins:
            return None

        query_lower = query.strip().lower()
        for coin in coins:
            if (
                coin.get("symbol", "").lower() == query_lower
                or coin.get("name", "").lower() == query_lower
            ):
                return coin
        # Fall back to CoinGecko's top-ranked search result (usually the coin people mean, e.g. "BTC" -> Bitcoin)
        return coins[0]

    def get_crypto_price(self, coin: str, vs_currency: str = "") -> str:
        """
        Get the current price, 24h change, market cap, and 24h volume for a cryptocurrency.

        :param coin: Cryptocurrency name or ticker symbol, e.g. "bitcoin", "BTC", "ethereum", "ETH", "dogecoin"
        :param vs_currency: Currency to price against, e.g. "usd", "eur". Leave blank to use the default configured currency.
        :return: A readable summary of the coin's current market data, or an honest error message if the lookup fails.
        """
        vs = (vs_currency or self.valves.vs_currency).strip().lower()

        match = self._resolve_coin(coin)
        if not match:
            return (
                f"Couldn't find a cryptocurrency matching '{coin}' on CoinGecko. "
                f"Try the full name (e.g. 'bitcoin') or the ticker symbol (e.g. 'BTC'), "
                f"or check https://www.coingecko.com directly."
            )

        coin_id = match["id"]
        coin_name = match.get("name", coin)
        coin_symbol = match.get("symbol", "").upper()

        try:
            resp = requests.get(
                "https://api.coingecko.com/api/v3/simple/price",
                params={
                    "ids": coin_id,
                    "vs_currencies": vs,
                    "include_market_cap": "true",
                    "include_24hr_vol": "true",
                    "include_24hr_change": "true",
                    "include_last_updated_at": "true",
                },
                timeout=self.valves.timeout_seconds,
            )
            resp.raise_for_status()
            data = resp.json()
        except requests.RequestException as e:
            return (
                f"Found {coin_name} ({coin_symbol}) but couldn't reach CoinGecko's price endpoint right now "
                f"({e.__class__.__name__}). Try again shortly, or check "
                f"https://www.coingecko.com/en/coins/{coin_id} directly."
            )

        info = data.get(coin_id)
        if not info or vs not in info:
            return (
                f"CoinGecko doesn't have {coin_name} ({coin_symbol}) priced in '{vs}'. "
                f"Try a common currency like 'usd' or 'eur', or check "
                f"https://www.coingecko.com/en/coins/{coin_id} directly."
            )

        price = info[vs]
        market_cap = info.get(f"{vs}_market_cap")
        vol_24h = info.get(f"{vs}_24h_vol")
        change_24h = info.get(f"{vs}_24h_change")
        last_updated = info.get("last_updated_at")

        lines = [f"{coin_name} ({coin_symbol}): {price:,.2f} {vs.upper()}"]
        if change_24h is not None:
            direction = "up" if change_24h >= 0 else "down"
            lines.append(f"24h change: {direction} {abs(change_24h):.2f}%")
        if market_cap is not None:
            lines.append(f"Market cap: {market_cap:,.0f} {vs.upper()}")
        if vol_24h is not None:
            lines.append(f"24h volume: {vol_24h:,.0f} {vs.upper()}")
        if last_updated:
            ts = datetime.fromtimestamp(last_updated, tz=timezone.utc).strftime(
                "%Y-%m-%d %H:%M UTC"
            )
            lines.append(f"Last updated: {ts}")

        return "\n".join(lines)
